export class SessionManager {
  constructor(private store: TokenStore, private clock: Clock) {}
  async getAccessToken(): Promise<string> {
    const t = await this.store.load();
    if (t.expiresAt - this.clock.now() < REFRESH_MARGIN_MS) {
      return this.refresh(t);
    }
    return t.accessToken;
  }
  private async refresh(t: Token): Promise<string> {
    const next = await refreshGrant(t.refreshToken);
    await this.store.save(next);
    return next.accessToken;
  }
}
