const cache = new LRU<string, ProductPage>({ max: 500, ttl: 60_000 });
export async function getProducts(req: Request): Promise<ProductPage> {
  const key = cacheKey(req.query);
  const hit = cache.get(key);
  if (hit) return hit;
  const page = await db.products.search(req.query);
  cache.set(key, page);
  return page;
